parts.text:
{
  "units": [
    {
      "quote": "8 FAM 103.1-1 Responsibilities of the Passport Specialist and Consular Officer\n\n(CT:CITZ-1; 06-27-2018)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "This text provides the section header, topic title, and administrative citation details without imposing any operative requirement or rule."
    },
    {
      "quote": "This section is a summary of your adjudicative responsibilities and is not all-inclusive.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "The provisions in this section serve only as an overview of adjudicative responsibilities rather than an exhaustive list."
    },
    {
      "quote": "Your full adjudicative responsibilities are provided in this and other sections of the 8 FAM, the 8 FAH-1, guides, and other guidance.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Complete adjudicative duties are established across this section, other sections of 8 FAM, 8 FAH-1, guides, and supplementary guidance materials."
    },
    {
      "quote": "Consular officers receive additional responsibilities in their work requirements and via ALDACs",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Consular officers obtain additional duties through their formal work requirements and through ALDAC communications."
    },
    {
      "quote": "Passport specialists receive additional responsibilities in their work commitments in the individual performance plan, via memoranda to the field from CA/PPT headquarters or regional/local management, and from other duties as assigned.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Passport specialists are assigned supplemental responsibilities via their individual performance plan work commitments, field memoranda issued by CA/PPT headquarters or regional/local management, and other assigned duties."
    },
    {
      "quote": "You must follow established adjudication and annotation procedures to ensure that the passport application and submitted documents are legible, accurate, and complete.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Adjudicators are obligated to adhere to established adjudication and annotation procedures to verify that both the passport application and all submitted records are legible, accurate, and complete."
    },
    {
      "quote": "The submitted documents must be issued and certified by the appropriate custodian of records, e.g., a government agency or court that issued and maintains the record.",
      "scope_quotes": [
        "You must follow established adjudication and annotation procedures to ensure that the passport application and submitted documents are legible, accurate, and complete."
      ],
      "kind": "requirement",
      "meaning": "Submitted documents are mandatory to be both issued and certified by the relevant custodian of records (such as an issuing and maintaining government agency or court)."
    },
    {
      "quote": "You must issue the passport application if the applicant is entitled to the passport, has met the standard of evidence for both identity and citizenship, the passport application is acceptable in its totality, and there are no other barriers to issuance.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Issuance of the passport application is mandatory if and only if all four conditions are met concurrently: the applicant is entitled to the passport, the evidentiary standard for both identity and citizenship is satisfied, the application is acceptable in its totality, and no other barriers to issuance exist."
    },
    {
      "quote": "You must ensure that the passport application is acceptable in its totality and resolve any outstanding issues by adjudicating the passport application to the extent possible and then suspending or referring, as appropriate, the passport application until adequate information and/or documentation is obtained.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Adjudicators are required to verify the overall acceptability of the passport application and resolve any unresolved issues by adjudicating it as far as possible, followed by either suspending or referring the application as appropriate until sufficient information, documentation, or both are secured."
    }
  ]
}
